"""Validator set membership and quorum threshold calculator."""

class ValidatorSet:
    def __init__(self, validators: list[str]):
        self.validators = list(validators)

    @property
    def size(self) -> int:
        return len(self.validators)

    def required_commit_quorum(self) -> int:
        # In PBFT (3f + 1), required commit quorum is 2f + 1
        # BUG: Uses naive (2 * N) // 3 which undercounts when N=4 (returns 2 instead of 3)!
        return (2 * self.size) // 3

