"""BFT block finalization engine."""

from typing import Dict, List
from bft_message import CommitVote
from validator_set import ValidatorSet


class BFTEngine:
    def __init__(self, val_set: ValidatorSet):
        self.val_set = val_set
        self.commit_votes: Dict[str, set[str]] = {}  # block_hash -> set(node_ids)

    def receive_vote(self, vote: CommitVote) -> bool:
        if vote.node_id not in self.val_set.validators:
            return False
        if vote.block_hash not in self.commit_votes:
            self.commit_votes[vote.block_hash] = set()
        self.commit_votes[vote.block_hash].add(vote.node_id)
        threshold = self.val_set.required_commit_quorum()
        return len(self.commit_votes[vote.block_hash]) >= threshold

