import math


class ValidatorSet:
    def __init__(self, validators: list[str]):
        self.validators = list(validators)

    @property
    def size(self) -> int:
        return len(self.validators)

    def required_commit_quorum(self) -> int:
        # For N = 3f + 1, f = (N - 1) // 3, required quorum = 2f + 1
        f = (self.size - 1) // 3
        return 2 * f + 1
